    "@types/react-dom": "19.0.0",
    "typescript": "5.7.3"
  }
}

import { Config } from "@remotion/cli/config";

Config.setVideoImageFormat("jpeg");
Config.setOverwriteOutput(true);
Config.setConcurrency(4);

/**
 * Palette for the grey-box animatic.
 *
 * Deliberately desaturated: in an animatic the only things allowed to carry
 * colour are the ones whose *timing* is being judged — packets, the approval
 * state change, and the lit card in the close. Everything else is grey so a
 * mistimed move is obvious rather than decorated over.
 */
export const C = {
  ground: "#0b0e12",
  groundLift: "#141920",

  cardFill: "#191f27",
  cardFillLift: "#20272f",
  cardStroke: "#2c3540",
  cardStrokeLit: "#46525f",
  chrome: "#232b34",

  skeleton: "#2e3843",
  skeletonLit: "#414d5a",

  ink: "#e6e9ed",
  muted: "#8f98a4",
  faint: "#5d6772",

  /** The only three hues in the film. */
  accent: "#3ec2b1", // Lobu / the context layer
  packet: "#e0a444", // an event crossing a boundary
  agent: "#a48cf7", // a terminal agent (Claude Code, Codex)
} as const;

export const FONT_MONO =
  'ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace';
export const FONT_SANS =
  'system-ui, -apple-system, "Segoe UI", Roboto, sans-serif';

import { Easing, interpolate } from "remotion";

export const FPS = 60;

/** Seconds → frames. Every timing in this project is authored in seconds. */
export const s = (seconds: number) => Math.round(seconds * FPS);

/**
 * The four moves from the composition spec. Nothing else is allowed to animate;
 * if a value needs a fifth curve, the shot is wrong, not the constant.
 */
export const MOVE = {
  /** Camera push / pull / pan across the table. */
  camera: s(0.32),
  /** A card entering or leaving. */
  handoff: s(0.42),
  /** An event chip crossing a card boundary. Twice in the whole film. */
  packet: s(0.2),
  /** Caption rise-and-fade. */
  captionIn: s(0.18),
  captionOut: s(0.14),
} as const;

/** The single easing curve. Two curves in one shot is the amateur tell. */
export const EASE = Easing.bezier(0.22, 1, 0.36, 1);

export const ease = (
  frame: number,
  from: number,
  to: number,
  out: [number, number] = [0, 1],
) =>
  interpolate(frame, [from, to], out, {
    easing: EASE,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

/** Linear ramp with clamped ends — for mechanical things like typing. */
export const ramp = (
  frame: number,
  from: number,
  to: number,
  out: [number, number] = [0, 1],
) =>
  interpolate(frame, [from, to], out, {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

/**
 * Beat boundaries in absolute frames. This is the contract the whole film is
 * checked against — if the animatic feels wrong, these numbers move first and
 * everything downstream follows.
 */
export const BEAT = {
  coldOpen: { from: s(0), to: s(8) },
  setup: { from: s(8), to: s(28) },
  map: { from: s(28), to: s(43) },
  causality: { from: s(43), to: s(58) },
  payoff: { from: s(58), to: s(78) },
  close: { from: s(78), to: s(90) },
} as const;

export const TOTAL = s(90);

/**
 * Table space.
 *
 * Every card in the film has ONE permanent address here and never moves. The
 * camera is what travels. That is the whole conceit of the composition: the
 * viewer is looking at one continuous surface from different distances, not at
 * a sequence of unrelated screen recordings.
 *
 * The close shot pulls back to show the entire table at once, so this layout is
 * also the final frame — the arrangement has to read as composed, not as
 * whatever order the beats happened to need.
 */

export type Rect = { x: number; y: number; w: number; h: number };

export const TABLE: Rect = { x: 0, y: 0, w: 4200, h: 1900 };

export const CARD = {
  /** Top row: the setup act reads left → right. */
  landing: { x: 120, y: 140, w: 1200, h: 680 },
  claude: { x: 1460, y: 140, w: 1240, h: 760 },
  lobuBoot: { x: 2840, y: 140, w: 1240, h: 760 },

  /** Bottom left: the Slack thread. Beats 1 and 5 are the same card. */
  slack: { x: 120, y: 980, w: 1140, h: 780 },

  /** Bottom middle: the four Lobu pages, laid out as a 2×2 map. */
  connectors: { x: 1460, y: 980, w: 620, h: 370 },
  agents: { x: 2140, y: 980, w: 620, h: 370 },
  behaviors: { x: 1460, y: 1400, w: 620, h: 370 },
  memory: { x: 2140, y: 1400, w: 620, h: 370 },

  /**
   * Bottom right: Codex and Activity are ADJACENT on purpose. The causality
   * shot is not a split-screen effect — it is a single camera rect wide enough
   * to hold both, which is why the packet can physically cross between them.
   */
  codex: { x: 2860, y: 980, w: 600, h: 790 },
  activity: { x: 3480, y: 980, w: 600, h: 790 },
} as const satisfies Record<string, Rect>;

export const pad = (r: Rect, by: number): Rect => ({
  x: r.x - by,
  y: r.y - by,
  w: r.w + by * 2,
  h: r.h + by * 2,
});

/** Centre of a rect, in table coordinates. */
export const centre = (r: Rect) => ({ x: r.x + r.w / 2, y: r.y + r.h / 2 });

import { CARD, pad, type Rect } from "./layout";
import { EASE, MOVE, s } from "./timing";
import { interpolate } from "remotion";

/**
 * A camera keyframe: at frame `at`, begin moving to `rect` over `dur` frames,
 * then hold until the next keyframe. Authoring the START of each move (rather
 * than the end) is what keeps the holds explicit — the gap between one move
 * ending and the next beginning IS the hold, and it is visible in this table.
 */
export type Key = { at: number; rect: Rect; dur: number };

/** Region inside the Slack card where the answer and its data window land. */
const SLACK_ANSWER: Rect = { x: 180, y: 1240, w: 900, h: 506 };
/** Region inside the Slack card holding the approval card. */
const SLACK_APPROVAL: Rect = { x: 180, y: 1400, w: 820, h: 461 };
/** Codex and Activity together — the causality frame. */
const CAUSALITY: Rect = { x: 2820, y: 940, w: 1300, h: 820 };
/** The four Lobu pages as one region. */
const MAP: Rect = { x: 1400, y: 920, w: 1420, h: 890 };
/** Everything. */
const WHOLE_TABLE: Rect = { x: -120, y: -140, w: 4440, h: 2180 };

export const CAMERA: Key[] = [
  // 1 · COLD OPEN — already in motion when the film starts.
  { at: s(0), rect: pad(CARD.slack, 100), dur: 1 },
  { at: s(0.4), rect: SLACK_ANSWER, dur: s(5.6) },

  // 2 · SETUP — three handoffs, left to right along the top row.
  { at: s(8), rect: pad(CARD.landing, 80), dur: MOVE.camera },
  { at: s(12), rect: pad(CARD.claude, 80), dur: MOVE.camera },
  { at: s(22), rect: pad(CARD.lobuBoot, 80), dur: MOVE.camera },

  // 3 · THE MAP — pull back to all four pages, then walk them.
  { at: s(28), rect: MAP, dur: s(0.5) },
  { at: s(29.6), rect: pad(CARD.connectors, 50), dur: MOVE.camera },
  { at: s(33.1), rect: pad(CARD.agents, 50), dur: MOVE.camera },
  { at: s(36.6), rect: pad(CARD.behaviors, 50), dur: MOVE.camera },
  { at: s(40.1), rect: pad(CARD.memory, 50), dur: MOVE.camera },

  // 4 · CAUSALITY — one rect holding both cards. No move for the whole beat;
  //     the stillness is what makes the packet the only thing moving.
  { at: s(43), rect: CAUSALITY, dur: s(0.5) },

  // 5 · PAYOFF — back to the Slack thread, then the only 1.4× push in the film.
  { at: s(58), rect: pad(CARD.slack, 70), dur: s(0.5) },
  { at: s(70.6), rect: SLACK_APPROVAL, dur: MOVE.camera },

  // 6 · CLOSE — one long pull back to the entire table.
  { at: s(78), rect: WHOLE_TABLE, dur: s(0.9) },
];

const lerpRect = (a: Rect, b: Rect, t: number): Rect => ({
  x: interpolate(t, [0, 1], [a.x, b.x]),
  y: interpolate(t, [0, 1], [a.y, b.y]),
  w: interpolate(t, [0, 1], [a.w, b.w]),
  h: interpolate(t, [0, 1], [a.h, b.h]),
});

export const cameraRectAt = (frame: number): Rect => {
  let idx = 0;
  for (let i = 0; i < CAMERA.length; i++) {
    if (CAMERA[i]!.at <= frame) idx = i;
  }
  const key = CAMERA[idx]!;
  if (idx === 0) return key.rect;

  const prev = CAMERA[idx - 1]!;
  const t = interpolate(frame, [key.at, key.at + key.dur], [0, 1], {
    easing: EASE,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return lerpRect(prev.rect, key.rect, t);
};

/** Contain-fit: the whole rect is always visible, never cropped. */
export const cameraTransform = (
  rect: Rect,
  viewW: number,
  viewH: number,
): string => {
  const scale = Math.min(viewW / rect.w, viewH / rect.h);
  const cx = rect.x + rect.w / 2;
  const cy = rect.y + rect.h / 2;
  return `translate(${viewW / 2}px, ${viewH / 2}px) scale(${scale}) translate(${-cx}px, ${-cy}px)`;
};

import React from "react";
import { useCurrentFrame } from "remotion";
import { C, FONT_MONO } from "../lib/theme";
import type { Rect } from "../lib/layout";
import { MOVE, ease } from "../lib/timing";

/**
 * A window on the table. Every capture in the finished film sits inside one of
 * these, which is what makes Slack and the Lobu UI read as the same physical
 * object rather than two unrelated screen grabs.
 *
 * In the animatic the interior is grey boxes — the point is to judge WHEN
 * things happen, not what they look like.
 */
export const Card: React.FC<{
  rect: Rect;
  title: string;
  tone?: "neutral" | "accent" | "agent";
  /** Local frame at which the card fades up. */
  enterAt?: number;
  /** 0–1. The close shot dims everything except one card. */
  dim?: number;
  children?: React.ReactNode;
}> = ({ rect, title, tone = "neutral", enterAt = 0, dim = 0, children }) => {
  const frame = useCurrentFrame();

  const stroke =
    tone === "accent" ? C.accent : tone === "agent" ? C.agent : C.cardStroke;
  const label = tone === "neutral" ? C.muted : stroke;

  const t = ease(frame, enterAt, enterAt + MOVE.handoff);
  const opacity = t * (1 - dim * 0.78);
  const scale = 0.965 + t * 0.035;

  return (
    <div
      style={{
        position: "absolute",
        left: rect.x,
        top: rect.y,
        width: rect.w,
        height: rect.h,
        borderRadius: 14,
        background: C.cardFill,
        border: `2px solid ${stroke}${tone === "neutral" ? "" : "cc"}`,
        boxShadow: "0 40px 90px rgba(0,0,0,0.45)",
        opacity,
        transform: `scale(${scale})`,
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
      }}
    >
      <div
        style={{
          height: 46,
          flex: "none",
          background: C.chrome,
          borderBottom: `1px solid ${C.cardStroke}`,
          display: "flex",
          alignItems: "center",
          gap: 8,
          padding: "0 16px",
        }}
      >
        <Dot />
        <Dot />
        <Dot />
        <span
          style={{
            fontFamily: FONT_MONO,
            fontSize: 17,
            letterSpacing: "0.06em",
            color: label,
            marginLeft: 10,
          }}
        >
          {title}
        </span>
      </div>
      <div style={{ position: "relative", flex: 1, padding: 22 }}>
        {children}
      </div>
    </div>
  );
};

const Dot: React.FC = () => (
  <span
    style={{
      width: 11,
      height: 11,
      borderRadius: 999,
      background: C.cardStroke,
      display: "block",
