import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { C, FONT_SANS } from "../lib/theme";
import { MOVE, ease, s } from "../lib/timing";

/**
 * With no voiceover these nineteen lines ARE the script. Two rules they are
 * checked against here:
 *   - never under 1.2s on screen
 *   - never more than seven words
 * Both are asserted at module load, because a caption that breaks either is a
 * silent failure — it renders fine and simply cannot be read.
 */
export type Caption = { from: number; to: number; text: string };

const cap = (from: number, to: number, text: string): Caption => ({
  from: s(from),
  to: s(to),
  text,
});

export const CAPTIONS: Caption[] = [
  // 1 · Cold open
  cap(1.2, 3.4, "Four systems. One answer."),
  cap(4.4, 7.4, "Nobody wrote an integration."),

  // 2 · Setup
  cap(8.6, 11.2, "Copy the prompt."),
  cap(13.0, 16.0, "It asks what you're building."),
  cap(17.5, 20.5, "Then it builds it."),
  cap(22.6, 26.5, "Three minutes, shown in ten seconds."),

  // 3 · The map
  cap(29.8, 32.6, "Connectors bring the systems in."),
  cap(33.3, 36.1, "Agents get scoped identities."),
  cap(36.8, 39.6, "Behaviors run on a schedule."),
  cap(40.3, 42.8, "Memory is shared and durable."),

  // 4 · Causality
  cap(44.0, 47.2, "A different agent. A different repo."),
  cap(49.5, 51.8, "Same memory."),
  cap(53.5, 57.2, "Nothing was integrated between them."),

  // 5 · Payoff
  cap(59.0, 62.0, "Ask it where the work happens."),
  cap(64.5, 67.5, "It asks before it acts."),
  cap(71.0, 74.4, "One click. The card rewrites itself."),
  cap(75.2, 77.6, "Every action, on the record."),

  // 6 · Close
  cap(80.0, 84.0, "AI as the operational layer."),
  cap(86.0, 89.5, "lobu.ai"),
];

for (const c of CAPTIONS) {
  if (c.to - c.from < s(1.2)) {
    throw new Error(`Caption under 1.2s on screen: "${c.text}"`);
  }
  if (c.text.split(/\s+/).length > 7) {
    throw new Error(`Caption over seven words: "${c.text}"`);
  }
}

export const Captions: React.FC = () => {
  const frame = useCurrentFrame();
  const active = CAPTIONS.find((c) => frame >= c.from && frame <= c.to);
  if (!active) return null;

  const inT = ease(frame, active.from, active.from + MOVE.captionIn);
  const outT = ease(frame, active.to - MOVE.captionOut, active.to);
  const opacity = inT * (1 - outT);
  const rise = (1 - inT) * 12;

  return (
    <AbsoluteFill
      style={{
        justifyContent: "flex-end",
        alignItems: "center",
        // The caption band owns the bottom 20% — every camera rect is composed
        // so nothing that matters is ever behind this.
        paddingBottom: 74,
      }}
    >
      <div
        style={{
          opacity,
          transform: `translateY(${rise}px)`,
          fontFamily: FONT_SANS,
          fontSize: 44,
          fontWeight: 600,
          letterSpacing: "-0.02em",
          color: C.ink,
          textShadow: "0 2px 24px rgba(0,0,0,0.85)",
          padding: "10px 26px",
        }}
      >
        {active.text}
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import { useCurrentFrame } from "remotion";
import { C, FONT_MONO } from "../lib/theme";
import { MOVE, ease } from "../lib/timing";

/**
 * An event crossing a card boundary.
 *
 * There are exactly two in the film, and each corresponds to a real row in the
 * event log. Scarcity is the whole reason they read as meaningful — a third one
 * used decoratively would turn the other two into decoration retroactively.
 */
export const Packet: React.FC<{
  /** Absolute frame at which the packet leaves. */
  at: number;
  from: { x: number; y: number };
  to: { x: number; y: number };
  label: string;
  /** How high the flight arcs, in table units. */
  lift?: number;
}> = ({ at, from, to, label, lift = 150 }) => {
  const frame = useCurrentFrame();
  const t = ease(frame, at, at + MOVE.packet);

  // Fade in on departure, out on arrival — the chip should never be seen
  // sitting still at either end.
  const opacity =
    ease(frame, at, at + 4) * (1 - ease(frame, at + MOVE.packet - 5, at + MOVE.packet + 6));
  if (opacity <= 0.001) return null;

  const cx = (from.x + to.x) / 2;
  const cy = (from.y + to.y) / 2 - lift;

  // Quadratic bezier at t.
  const u = 1 - t;
  const x = u * u * from.x + 2 * u * t * cx + t * t * to.x;
  const y = u * u * from.y + 2 * u * t * cy + t * t * to.y;

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        transform: "translate(-50%, -50%)",
        opacity,
        background: C.packet,
        color: C.ground,
        fontFamily: FONT_MONO,
        fontSize: 20,
        letterSpacing: "0.08em",
        fontWeight: 600,
        padding: "8px 16px",
        borderRadius: 8,
        whiteSpace: "nowrap",
        boxShadow: `0 0 40px ${C.packet}66`,
      }}
    >
      {label}
    </div>
  );
};

