import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig } from "remotion";
import { cameraRectAt, cameraTransform } from "./lib/camera";
import { CARD, TABLE } from "./lib/layout";
import { C, FONT_MONO, FONT_SANS } from "./lib/theme";
import { ease, s } from "./lib/timing";
import { Card } from "./components/Card";
import { Captions } from "./components/Captions";
import { Packet } from "./components/Packet";
import {
  ActivityMock,
  BrowserMock,
  CodexMock,
  LandingMock,
  PageMock,
  SlackMock,
  TerminalMock,
} from "./components/Mocks";

/**
 * The 90-second reel, as a grey-box animatic.
 *
 * Nothing here is footage. The point is to prove the SHAPE — whether the camera
 * arrives before the caption, whether the causality beat has room to breathe,
 * whether the approval hold is long enough to read — before anyone spends a day
 * capturing real screens against the wrong timings.
 */
export const Reel: React.FC = () => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const rect = cameraRectAt(frame);
  const transform = cameraTransform(rect, width, height);

  // The close dims everything that is not a Lobu surface.
  const dim = ease(frame, s(80.6), s(81.4));

  return (
    <AbsoluteFill style={{ background: C.ground, overflow: "hidden" }}>
      {/* the table — one continuous surface, never re-established */}
      <div
        style={{
          position: "absolute",
          width: TABLE.w,
          height: TABLE.h,
          transformOrigin: "0 0",
          transform,
          background: `radial-gradient(1400px 900px at 30% 40%, ${C.groundLift}, ${C.ground} 70%)`,
        }}
      >
        <Card rect={CARD.slack} title="#eng-leads — Slack" enterAt={0} dim={dim}>
          <SlackMock />
        </Card>

        <Card rect={CARD.landing} title="lobu.ai" enterAt={s(7.6)} dim={dim}>
          <LandingMock />
        </Card>

        <Card
          rect={CARD.claude}
          title="claude code"
          tone="agent"
          enterAt={s(11.6)}
          dim={dim}
        >
          <TerminalMock />
        </Card>

        <Card
          rect={CARD.lobuBoot}
          title="localhost:8787"
          tone="accent"
          enterAt={s(21.6)}
        >
          <BrowserMock />
        </Card>

        <Card rect={CARD.connectors} title="connectors" tone="accent" enterAt={s(27.4)}>
          <PageMock kind="grid" />
        </Card>
        <Card rect={CARD.agents} title="agents" tone="accent" enterAt={s(27.4)}>
          <PageMock kind="list" />
        </Card>
        <Card rect={CARD.behaviors} title="behaviors" tone="accent" enterAt={s(27.4)}>
          <PageMock kind="rows" />
        </Card>
        <Card rect={CARD.memory} title="memory" tone="accent" enterAt={s(27.4)}>
          <PageMock kind="graph" />
        </Card>

        <Card
          rect={CARD.codex}
          title="codex — other-repo"
          tone="agent"
          enterAt={s(42.6)}
          dim={dim}
        >
          <CodexMock />
        </Card>
        <Card
          rect={CARD.activity}
          title="lobu — activity"
          tone="accent"
          enterAt={s(42.6)}
        >
          <ActivityMock />
        </Card>

        {/* The two packets. Both correspond to a real row in the event log. */}
        <Packet
          at={s(46.5)}
          from={{ x: 3380, y: 1320 }}
          to={{ x: 3620, y: 1085 }}
          label="◈ EVENT WRITTEN"
          lift={130}
        />
        <Packet
          at={s(72.1)}
          from={{ x: 880, y: 1560 }}
          to={{ x: 1180, y: 1430 }}
          label="◈ TO ACTIVITY"
          lift={90}
        />
      </div>

      <Captions />
      <EndCard />
    </AbsoluteFill>
  );
};

/** The only hard cut in the film. */
const EndCard: React.FC = () => {
  const frame = useCurrentFrame();
  const inT = ease(frame, s(85.4), s(85.6));
  if (inT <= 0.001) return null;
  const text = ease(frame, s(85.9), s(86.6));

  return (
    <AbsoluteFill
      style={{
        background: "#000",
        opacity: inT,
        alignItems: "center",
        justifyContent: "center",
        flexDirection: "column",
        gap: 26,
      }}
    >
      <div
        style={{
          opacity: text,
          fontFamily: FONT_SANS,
          fontSize: 58,
          fontWeight: 650,
          letterSpacing: "-0.03em",
          color: C.ink,
        }}
      >
        Make every agent multiplayer.
      </div>
      <div
        style={{
          opacity: text,
          fontFamily: FONT_MONO,
          fontSize: 28,
          letterSpacing: "0.16em",
          color: C.accent,
        }}
      >
        lobu.ai
      </div>
    </AbsoluteFill>
  );
};

import React from "react";
import { Composition, Folder } from "remotion";
import { Reel } from "./Reel";
import { BEAT, FPS, TOTAL } from "./lib/timing";
import { BeatPreview } from "./BeatPreview";

/**
 * The full reel, plus one composition per beat so a single beat can be
 * re-timed and watched in isolation without scrubbing the whole 90 seconds.
 */
export const RemotionRoot: React.FC = () => {
  return (
    <>
      <Composition
        id="Reel"
        component={Reel}
        durationInFrames={TOTAL}
        fps={FPS}
        width={1920}
        height={1080}
      />
      <Folder name="Beats">
        {(
          [
            ["1-ColdOpen", BEAT.coldOpen],
            ["2-Setup", BEAT.setup],
            ["3-Map", BEAT.map],
            ["4-Causality", BEAT.causality],
            ["5-Payoff", BEAT.payoff],
            ["6-Close", BEAT.close],
          ] as const
        ).map(([id, beat]) => (
          <Composition
            key={id}
            id={id}
            component={BeatPreview}
            durationInFrames={beat.to - beat.from}
            fps={FPS}
            width={1920}
            height={1080}
            defaultProps={{ startFrame: beat.from }}
          />
        ))}
      </Folder>
    </>
  );
};

import React from "react";
import { Sequence } from "remotion";
import { Reel } from "./Reel";

export type BeatPreviewProps = { startFrame: number };

/**
 * Plays the reel from an arbitrary frame while keeping every absolute timing
 * intact. A negative `from` shifts the whole film back so local frame 0 is the
 * beat's first frame — the mocks still read their own absolute cues, so nothing
 * has to be re-authored to preview a beat.
 */
export const BeatPreview: React.FC<BeatPreviewProps> = ({ startFrame }) => (
  <Sequence from={-startFrame} layout="none">
    <Reel />
  </Sequence>
);

import { registerRoot } from "remotion";
import { RemotionRoot } from "./Root";

registerRoot(RemotionRoot);

