/** Contain-fit: the whole rect is always visible, never cropped. */
export const cameraTransform = (
  rect: Rect,
  viewW: number,
  viewH: number,
): string => {
  const scale = Math.min(viewW / rect.w, viewH / rect.h);
  const cx = rect.x + rect.w / 2;
  const cy = rect.y + rect.h / 2;
  return `translate(${viewW / 2}px, ${viewH / 2}px) scale(${scale}) translate(${-cx}px, ${-cy}px)`;
};

input.new_string:
/**
 * Height reserved at the bottom of frame for the caption band.
 *
 * The camera fits into the region ABOVE this, which is what enforces the
 * composition rule globally: no shot can accidentally put something readable
 * behind a caption, because no shot is ever composed down there in the first
 * place.
 */
export const CAPTION_BAND = 190;

/** Contain-fit into the frame above the caption band. Never crops the rect. */
export const cameraTransform = (
  rect: Rect,
  viewW: number,
  viewH: number,
): string => {
  const stage = viewH - CAPTION_BAND;
  const scale = Math.min(viewW / rect.w, stage / rect.h);
  const cx = rect.x + rect.w / 2;
  const cy = rect.y + rect.h / 2;
  return `translate(${viewW / 2}px, ${stage / 2}px) scale(${scale}) translate(${-cx}px, ${-cy}px)`;
};

