import React from "react";
import { Video } from "@remotion/media";
import { staticFile, useCurrentFrame } from "remotion";
import type { Rect } from "../lib/layout";
import { MOVE, ease } from "../lib/timing";

/**
 * A real screen recording, sitting at a card's address on the table.
 *
 * testreel already draws the macOS window chrome, so this deliberately does NOT
 * wrap the footage in the grey-box `<Card>` — that would put a window inside a
 * window. The capture IS the card.
 *
 * As each beat's footage lands, its `<Card>` in Reel.tsx is swapped for one of
 * these. Until then the grey box stands in, so the film always plays end to end
 * rather than breaking while capture is half-done.
 */
export const CaptureCard: React.FC<{
  rect: Rect;
  /** File under public/capture/, e.g. "landing.webm". */
  src: string;
  /** Absolute frame at which the card appears and its footage starts. */
  enterAt: number;
  /** Seconds to skip from the head of the recording. */
  trimBefore?: number;
  dim?: number;
}> = ({ rect, src, enterAt, trimBefore = 0, dim = 0 }) => {
  const frame = useCurrentFrame();

  const t = ease(frame, enterAt, enterAt + MOVE.handoff);
  if (t <= 0.001) return null;

  return (
    <div
      style={{
        position: "absolute",
        left: rect.x,
        top: rect.y,
        width: rect.w,
        height: rect.h,
        opacity: t * (1 - dim * 0.78),
        transform: `scale(${0.965 + t * 0.035})`,
        borderRadius: 14,
        overflow: "hidden",
        boxShadow: "0 40px 90px rgba(0,0,0,0.45)",
      }}
    >
      <Video
        src={staticFile(`capture/${src}`)}
        trimBefore={trimBefore}
        // The footage is timed to the beat, not the other way round: it starts
        // when the camera arrives and holds its last frame afterwards.
        startFrom={0}
        style={{ width: "100%", height: "100%", objectFit: "cover" }}
      />
    </div>
  );
};

result.output:
# Authentication

Most web apps require authentication. Testreel supports several approaches so your recordings start in a logged-in state without capturing the login flow on video.

## Setup block (recommended)

The `setup` block runs steps **before** video recording starts. Session state (cookies, localStorage, etc.) is automatically carried over into the recorded session.

```json
{
  "url": "https://app.example.com/dashboard",
  "setup": {
    "url": "https://app.example.com/login",
    "steps": [
      { "action": "fill", "selector": "#email", "text": "user@example.com" },
      { "action": "fill", "selector": "#password", "text": "s3cret" },
      { "action": "click", "selector": "button[type=submit]" },
      { "action": "wait", "ms": 2000 }
    ]
  },
  "steps": [
    { "action": "screenshot", "name": "dashboard" }
  ]
}
```

The setup block accepts:
- `url` (optional) — the page to navigate to for setup. Defaults to the main `url`.
- `steps` — same actions as the recording. Cursor is disabled during setup.

Setup also preserves scroll position — if your setup scrolls to a specific section, the recording starts at that position.

You can also provide setup in a separate file via the CLI:

```bash
npx testreel recording.json --setup login-steps.json
```

## localStorage injection

For apps that store auth tokens in localStorage (e.g., Supabase, Firebase):

```json
{
  "url": "https://app.example.com",
  "localStorage": {
    "sb-auth-token": "{\"access_token\":\"eyJ...\",\"refresh_token\":\"abc\"}"
  },
  "steps": [...]
}
```

Testreel navigates to the URL, injects the entries, then reloads to let the app pick up the session.

## Cookies

```json
{
  "url": "https://app.example.com",
  "cookies": [
    {
      "name": "session",
      "value": "abc123",
      "domain": "app.example.com",
      "path": "/"
    }
  ],
  "steps": [...]
}
```

