private func observe(_ input: [String: AnyJSONValue]) async throws -> [String: Any] {
    let tmp = FileManager.default.temporaryDirectory
        .appendingPathComponent("lobu-peekaboo-see-\(UUID().uuidString).png")
    let target = input.object("target") ?? [:]
    var args = ["see", "--path", tmp.path, "--capture-engine", "classic"]
    if let windowID = target.int("window_id") { args += ["--window-id", String(windowID)] }
    else if let app = target.string("app") { args += ["--app", app] }
    else { args += ["--app", "frontmost"] }
    if let title = target.string("window_title") { args += ["--window-title", title] }
    var out = try await runPeekabooJSON(args)
    if input.bool("include_image_base64") == true, let data = try? Data(contentsOf: tmp) {
        out["image"] = [
            "mime_type": "image/png",
            "size_bytes": data.count,
            "data_base64": data.base64EncodedString(),
        ]
    }
    try? FileManager.default.removeItem(at: tmp)
    if let max = input.int("max_elements"),
       var data = out["data"] as? [String: Any],
       let els = data["ui_elements"] as? [Any],
       els.count > max {
        data["ui_elements"] = Array(els.prefix(max))
        data["truncated"] = true
        out["data"] = data
    }
    return out
}

private func click(_ input: [String: AnyJSONValue]) async throws -> [String: Any] {
    if input.double("x") != nil, input.double("y") != nil {
        return try clickNative(input)
    }
    var args = ["click"]
    if let element = input.string("element_id") { args += ["--on", element] }
    else if let query = input.string("query") { args.append(query) }
    else { throw ComputerUseError.invalidInput("click requires element_id, query, or x/y") }
    addCommonTargetArgs(input, to: &args)
    if let snapshot = input.string("snapshot_id") { args += ["--snapshot", snapshot] }
    switch input.string("click_type") ?? "single" {
    case "double": args.append("--double")
    case "right": args.append("--right")
