    private func runPeekabooJSON(_ args: [String]) async throws -> [String: Any] {
        let binary = try resolvePeekabooBinary()
        return try await Task.detached(priority: .userInitiated) {
            let proc = Process()
            proc.executableURL = URL(fileURLWithPath: binary)
            // In-process only (flag follows the subcommand). Skips the Homebrew
            // peekaboo daemon so users grant TCC once on Owletto.
            proc.arguments = args + ["--no-remote", "--json"]
            var env = ProcessInfo.processInfo.environment
            // Make Homebrew/npm-installed helpers discoverable to any nested tool
            // Peekaboo might spawn (and mirror our CLI smoke environment).
            env["PATH"] = [
                env["PATH"],
                "/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin",
            ].compactMap { $0 }.joined(separator: ":")
            proc.environment = env

            let stdout = Pipe()
            let stderr = Pipe()
            proc.standardOutput = stdout
            proc.standardError = stderr
            try proc.run()
            proc.waitUntilExit()
            let out = stdout.fileHandleForReading.readDataToEndOfFile()
            let err = stderr.fileHandleForReading.readDataToEndOfFile()
            let stderrText = String(data: err, encoding: .utf8) ?? ""
            guard proc.terminationStatus == 0 else {
                let body = String(data: out, encoding: .utf8) ?? ""
                throw ComputerUseError.peekabooFailed("peekaboo \(args.joined(separator: " ")) failed (\(proc.terminationStatus)): \(body.isEmpty ? stderrText : body)")
            }
            guard
                let json = try JSONSerialization.jsonObject(with: out) as? [String: Any]
            else {
                throw ComputerUseError.peekabooFailed("peekaboo returned non-object JSON: \(String(data: out, encoding: .utf8) ?? "<binary>")")
            }
            if json["success"] as? Bool == false {
                throw ComputerUseError.peekabooFailed(String(describing: json["error"] ?? json))
            }
            var result = json
            if !stderrText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                result["stderr"] = stderrText
            }
            return result
        }.value
    }

