337	            case "shift", "⇧": flags.insert(.maskShift)
338	            case "alt", "option", "⌥": flags.insert(.maskAlternate)
339	            case "ctrl", "control", "⌃": flags.insert(.maskControl)
340	            default: keyToken = token
341	            }
342	        }
343	        guard let keyToken, let keyCode = Self.keyCode(for: keyToken) else {
344	            throw ComputerUseError.invalidInput("unsupported hotkey: \(keys)")
345	        }
