347	        let down = CGEvent(keyboardEventSource: src, virtualKey: keyCode, keyDown: true)
348	        down?.flags = flags
349	        down?.post(tap: .cghidEventTap)
350	        if holdMs > 0 { Thread.sleep(forTimeInterval: Double(holdMs) / 1000.0) }
351	        let up = CGEvent(keyboardEventSource: src, virtualKey: keyCode, keyDown: false)
352	        up?.flags = flags
353	        up?.post(tap: .cghidEventTap)
