import AppKit
import ApplicationServices
import Foundation

// MARK: - Native accessibility tree (replaces the Peekaboo `see` subprocess)
//
// Why this exists rather than shelling out: the Peekaboo subprocess carries its
// own bundle id, so it re-asks for TCC even when Owletto is already granted —
// and that prompt waits for a human. `runPeekabooJSON` waited on the process
// with an unbounded `waitUntilExit()`, so an unattended Mac wedged the device
// worker permanently: the last log line before the device went dark was
// `executing observe`, twice out of twice.
//
// Everything below is bounded by construction. `AXUIElementSetMessagingTimeout`
// caps each individual AX call, `deadline` caps the whole walk, and
// `maxElements` caps the output. An app that stops answering costs us a bounded
// wait and a partial tree — never the worker.
//
// This continues the migration `listWindows` already started; its comment says
// the same thing ("screen capture APIs must run in Owletto's process").

/// One accessible element, flattened out of the AX tree.
struct ObservedElement: Equatable {
    let id: String
    let role: String
    let title: String
    let label: String
    let frame: CGRect
    let enabled: Bool

    /// Centre point in top-left-origin screen coordinates — what `click` needs.
    var centre: CGPoint { CGPoint(x: frame.midX, y: frame.midY) }

    /// Text a `query` is matched against.
    var haystack: String { "\(title) \(label) \(role)" }

    func matches(query: String) -> Bool {
        let needle = query.trimmingCharacters(in: .whitespaces)
        guard !needle.isEmpty else { return false }
        return haystack.localizedCaseInsensitiveContains(needle)
    }

    var asJSON: [String: Any] {
        [
            "id": id,
            "role": role,
            "title": title,
            "label": label,
            "enabled": enabled,
            "bounds": [[Int(frame.origin.x), Int(frame.origin.y)],
                       [Int(frame.width), Int(frame.height)]],
        ]
    }
}

/// Bounded store mapping a `snapshot_id` back to the elements `observe` returned,
/// so a later `click`/`scroll` can resolve `elem_12` without re-walking.
///
/// In-memory is correct here: this is per-device UI state on one Mac, not shared
/// server state, and a stale snapshot must fail rather than be reconstructed.
final class ObserveSnapshotStore {
    static let shared = ObserveSnapshotStore()

    /// Keeping the last few is enough for the observe→act loop, and bounds the
    /// memory a long-lived menu-bar app holds.
    private let capacity = 8
    private var order: [String] = []
    private var snapshots: [String: [ObservedElement]] = [:]
    private let lock = NSLock()

    init(capacity: Int = 8) {
        self.capacity = max(1, capacity)
    }

    @discardableResult
    func put(_ elements: [ObservedElement], id: String = UUID().uuidString) -> String {
        lock.lock()
        defer { lock.unlock() }
        snapshots[id] = elements
        order.append(id)
        while order.count > capacity, let oldest = order.first {
            order.removeFirst()
            snapshots.removeValue(forKey: oldest)
        }
        return id
    }

    func get(_ id: String) -> [ObservedElement]? {
        lock.lock()
        defer { lock.unlock() }
        return snapshots[id]
    }

    func clear() {
        lock.lock()
        defer { lock.unlock() }
        order.removeAll()
        snapshots.removeAll()
    }
}

enum AccessibilityTree {
    /// Per-AX-call ceiling. An app that has stopped answering its accessibility
    /// port costs us this much and no more.
    static let messagingTimeout: Float = 0.4
    /// Whole-walk ceiling. Belt and braces: a huge tree of *fast* replies would
    /// still finish, so the element cap alone is not a time bound.
    static let walkBudget: TimeInterval = 3.0

    /// Flatten the accessibility tree of `pid` into at most `maxElements` items.
    ///
    /// Returns whatever it collected when it hits either bound — a partial tree
    /// is useful, a hang is not.
    static func walk(
        pid: pid_t,
        maxElements: Int,
        deadline: Date = Date().addingTimeInterval(walkBudget),
        makeRoot: (pid_t) -> AXUIElement = AXUIElementCreateApplication
    ) -> (elements: [ObservedElement], truncated: Bool) {
        let root = makeRoot(pid)
        AXUIElementSetMessagingTimeout(root, messagingTimeout)

        var collected: [ObservedElement] = []
        var queue: [AXUIElement] = [root]
        var truncated = false
        var index = 0

        while !queue.isEmpty {
            if collected.count >= maxElements || Date() >= deadline {
                truncated = true
                break
            }
            let element = queue.removeFirst()

            if let observed = describe(element, index: index + 1) {
                collected.append(observed)
                index += 1
            }
            queue.append(contentsOf: children(of: element))
        }
        return (collected, truncated)
    }

    /// Read one element's attributes. Elements with no frame (containers,
    /// offscreen items) are skipped — nothing can be clicked at no coordinates.
    static func describe(_ element: AXUIElement, index: Int) -> ObservedElement? {
        guard let frame = frame(of: element) else { return nil }
        guard frame.width > 0, frame.height > 0 else { return nil }
        return ObservedElement(
            id: "elem_\(index)",
            role: string(element, kAXRoleAttribute) ?? "",
            title: string(element, kAXTitleAttribute) ?? "",
            label: string(element, kAXDescriptionAttribute)
                ?? string(element, kAXValueAttribute)
                ?? "",
            frame: frame,
            enabled: bool(element, kAXEnabledAttribute) ?? true
        )
    }

    static func children(of element: AXUIElement) -> [AXUIElement] {
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, kAXChildrenAttribute as CFString, &value) == .success,
              let raw = value as? [AXUIElement] else {
            return []
        }
        return raw
    }

    static func frame(of element: AXUIElement) -> CGRect? {
        var positionRef: CFTypeRef?
        var sizeRef: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, kAXPositionAttribute as CFString, &positionRef) == .success,
              AXUIElementCopyAttributeValue(element, kAXSizeAttribute as CFString, &sizeRef) == .success else {
            return nil
        }
        var origin = CGPoint.zero
        var size = CGSize.zero
        // swiftlint:disable:next force_cast
        guard AXValueGetValue(positionRef as! AXValue, .cgPoint, &origin),
              AXValueGetValue(sizeRef as! AXValue, .cgSize, &size) else {
            return nil
        }
        return CGRect(origin: origin, size: size)
    }

    static func string(_ element: AXUIElement, _ attribute: String) -> String? {
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, attribute as CFString, &value) == .success else {
            return nil
        }
        if let text = value as? String { return text.isEmpty ? nil : text }
        return nil
    }

    static func bool(_ element: AXUIElement, _ attribute: String) -> Bool? {
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, attribute as CFString, &value) == .success else {
            return nil
        }
        return value as? Bool
    }

    /// Resolve the element a `click`/`scroll` is aimed at.
    ///
    /// `element_id` is exact and fails loudly when the snapshot has expired —
    /// silently falling back to a fresh walk would click a *different* element
    /// than the caller saw, which is worse than an error.
    static func resolve(
        elementID: String?,
        query: String?,
        in elements: [ObservedElement]
    ) throws -> ObservedElement {
        if let elementID {
            guard let hit = elements.first(where: { $0.id == elementID }) else {
                throw ComputerUseError.invalidInput(
                    "element \(elementID) is not in this snapshot — call observe again"
                )
            }
            return hit
        }
        if let query {
            let matches = elements.filter { $0.matches(query: query) }
            guard let best = matches.min(by: { $0.haystack.count < $1.haystack.count }) else {
                throw ComputerUseError.invalidInput("no element matched query '\(query)'")
            }
            return best
        }
        throw ComputerUseError.invalidInput("click requires element_id, query, or x/y")
    }
}

