// MARK: - Observe + element-targeted actions (formerly the Peekaboo `see` path)

func observeNative(_ input: [String: AnyJSONValue]) throws -> [String: Any] {
    try requireAccessibilityAccess()
    let target = input.object("target") ?? [:]
    let pid = try resolveTargetPID(target)
    // Clamp to the manifest's declared bounds rather than trusting the caller.
    let maxElements = min(max(input.int("max_elements") ?? 200, 1), 1000)

    let walked = AccessibilityTree.walk(pid: pid, maxElements: maxElements)
    let snapshotID = ObserveSnapshotStore.shared.put(walked.elements)

    var data: [String: Any] = [
        "snapshot_id": snapshotID,
        "ui_elements": walked.elements.map(\.asJSON),
        "element_count": walked.elements.count,
        "pid": Int(pid),
    ]
    if walked.truncated { data["truncated"] = true }

    var out: [String: Any] = ["success": true]
    // Screenshot is opt-out; a failure here must not lose the tree we walked.
    if input.bool("include_screenshot") != false, CGPreflightScreenCaptureAccess() {
        if let windowID = try? resolveWindowID(target.isEmpty ? ["app": .string("frontmost")] : target),
           let image = CGWindowListCreateImage(
               .null,
               .optionIncludingWindow,
               CGWindowID(windowID),
               [.boundsIgnoreFraming, .bestResolution]
           ) {
            data["window_id"] = windowID
            data["screenshot"] = ["width": image.width, "height": image.height]
            if input.bool("include_image_base64") == true, let png = Self.pngData(from: image) {
                out["image"] = [
                    "mime_type": "image/png",
                    "size_bytes": png.count,
                    "data_base64": png.base64EncodedString(),
                ]
            }
        }
    }
    out["data"] = data
    return out
}

func clickElementNative(_ input: [String: AnyJSONValue]) throws -> [String: Any] {
    try requireInputAccess()
    let hit = try resolveElement(input)
    var coords = input
    coords["x"] = .double(hit.centre.x)
    coords["y"] = .double(hit.centre.y)
    var out = try clickNative(coords)
    var data = out["data"] as? [String: Any] ?? [:]
    data["element_id"] = hit.id
    data["role"] = hit.role
    data["title"] = hit.title
    out["data"] = data
    return out
}

func scrollTargetNative(_ input: [String: AnyJSONValue]) throws -> [String: Any] {
    try requireInputAccess()
    let hit = try resolveElement(input)
    // Scroll events land wherever the pointer is, so aim it first.
    _ = try moveMouseNative(["x": .double(hit.centre.x), "y": .double(hit.centre.y)])
    var out = try scrollNative(input)
    var data = out["data"] as? [String: Any] ?? [:]
    data["element_id"] = hit.id
    out["data"] = data
    return out
}

func focusWindowByTitleNative(_ input: [String: AnyJSONValue]) throws -> [String: Any] {
    try requireAccessibilityAccess()
    guard let wanted = input.string("window_title") else {
        throw ComputerUseError.invalidInput("focus_window requires window_title")
    }
    let listing = try listWindowsNativeForFocus(input)
    guard let match = listing.first(where: {
        ($0["title"] as? String ?? "").localizedCaseInsensitiveContains(wanted)
    }), let windowID = match["windowID"] as? Int else {
        throw ComputerUseError.invalidInput("no window title matched '\(wanted)'")
    }
    let pid = try pidForWindowID(windowID)
    guard let app = NSRunningApplication(processIdentifier: pid) else {
        throw ComputerUseError.peekabooFailed("No running app for window \(windowID)")
    }
    app.activate(options: [.activateIgnoringOtherApps])
    // Activating raises the app; AXRaise picks the specific window when the
    // app has several. Best-effort — activation alone is already correct.
    raiseAXWindow(pid: pid, titleContains: wanted)
    return [
        "success": true,
        "data": ["window_id": windowID, "pid": Int(pid), "title": match["title"] as? String ?? ""],
    ]
}

/// Elements a `click`/`scroll` resolves against: a prior snapshot when one is
/// named, otherwise a fresh walk of the target.
private func resolveElement(_ input: [String: AnyJSONValue]) throws -> ObservedElement {
    let elements: [ObservedElement]
    if let snapshotID = input.string("snapshot_id") {
        guard let stored = ObserveSnapshotStore.shared.get(snapshotID) else {
            throw ComputerUseError.invalidInput(
                "snapshot \(snapshotID) has expired — call observe again"
            )
        }
        elements = stored
    } else {
        let pid = try resolveTargetPID(input)
        elements = AccessibilityTree.walk(pid: pid, maxElements: 1000).elements
    }
    return try AccessibilityTree.resolve(
        elementID: input.string("element_id"),
        query: input.string("query"),
        in: elements
    )
}

func resolveTargetPID(_ target: [String: AnyJSONValue]) throws -> pid_t {
    if let windowID = target.int("window_id") { return try pidForWindowID(windowID) }
    if let app = target.string("app"), app != "frontmost" {
        if app.hasPrefix("PID:"), let pid = pid_t(app.dropFirst(4)) { return pid }
        guard let running = Self.resolveRunningApp(named: app) else {
            throw ComputerUseError.invalidInput("App not found: \(app)")
        }
        return running.processIdentifier
    }
    guard let front = NSWorkspace.shared.frontmostApplication?.processIdentifier else {
        throw ComputerUseError.peekabooFailed("No frontmost application")
    }
    return front
}

func requireAccessibilityAccess() throws {
    guard AXIsProcessTrusted() else {
        throw ComputerUseError.peekabooFailed(
            "Accessibility permission is required. Enable Owletto in System Settings > Privacy & Security > Accessibility."
        )
    }
}

private func raiseAXWindow(pid: pid_t, titleContains: String) {
    let appElement = AXUIElementCreateApplication(pid)
    AXUIElementSetMessagingTimeout(appElement, AccessibilityTree.messagingTimeout)
    var value: CFTypeRef?
    guard AXUIElementCopyAttributeValue(appElement, kAXWindowsAttribute as CFString, &value) == .success,
          let windows = value as? [AXUIElement] else { return }
    for window in windows {
        let title = AccessibilityTree.string(window, kAXTitleAttribute) ?? ""
        if title.localizedCaseInsensitiveContains(titleContains) {
            AXUIElementPerformAction(window, kAXRaiseAction as CFString)
            return
        }
    }
}

