func requireScreenAccess() throws {

/// On-screen, layer-0 windows, optionally narrowed to one app. Single source
/// for `list_windows`, `focus_window --window-title`, and window capture, so
/// the three cannot disagree about what counts as a window.
func enumerateWindows(appName: String?) throws -> [[String: Any]] {
    guard CGPreflightScreenCaptureAccess() else {
        throw ComputerUseError.peekabooFailed(
            "Screen recording permission is required. Please grant it in System Settings > Privacy & Security > Screen Recording."
        )
    }
    let wanted = appName ?? "frontmost"
    let targetPID: pid_t? = {
        if wanted == "frontmost" {
            return NSWorkspace.shared.frontmostApplication?.processIdentifier
        }
        return Self.resolveRunningApp(named: wanted)?.processIdentifier
    }()
    let options: CGWindowListOption = [.optionOnScreenOnly, .excludeDesktopElements]
    guard let windowInfoList = CGWindowListCopyWindowInfo(options, kCGNullWindowID) as? [[String: Any]] else {
        throw ComputerUseError.peekabooFailed("Failed to enumerate windows")
    }
    var windows: [[String: Any]] = []
    var index = 0
    for info in windowInfoList {
        guard let layer = info[kCGWindowLayer as String] as? Int, layer == 0,
              let windowID = info[kCGWindowNumber as String] as? Int,
              let ownerPID = info[kCGWindowOwnerPID as String] as? pid_t else { continue }
        if let targetPID, ownerPID != targetPID { continue }
        let boundsDict = info[kCGWindowBounds as String] as? [String: CGFloat] ?? [:]
        windows.append([
            "windowID": windowID,
            "index": index,
            "title": info[kCGWindowName as String] as? String ?? "",
            "bounds": [
                [Int(boundsDict["X"] ?? 0), Int(boundsDict["Y"] ?? 0)],
                [Int(boundsDict["Width"] ?? 0), Int(boundsDict["Height"] ?? 0)],
            ],
            "isMinimized": false,
            "isMainWindow": index == 0,
        ])
        index += 1
    }
    return windows
}

