/// Flatten the accessibility tree of `pid` into at most `maxElements` items.
///
/// Returns whatever it collected when it hits either bound — a partial tree
/// is useful, a hang is not.
static func walk(
    pid: pid_t,
    maxElements: Int,
    deadline: Date = Date().addingTimeInterval(walkBudget)
) -> (elements: [ObservedElement], truncated: Bool) {
    let root = AXUIElementCreateApplication(pid)
    AXUIElementSetMessagingTimeout(root, messagingTimeout)
    return flatten(
        root: root,
        children: children(of:),
        describe: describe(_:index:),
        maxElements: maxElements,
        deadline: deadline
    )
}

/// Breadth-first traversal with both bounds applied, generic over the node
/// type so the bounds can be tested without a live accessibility tree.
///
/// The bounds ARE the fix — an unbounded walk is what let a single
/// unresponsive app take the device worker down — so they get tested
/// directly rather than inferred from a passing integration run.
static func flatten<Node>(
    root: Node,
    children: (Node) -> [Node],
    describe: (Node, Int) -> ObservedElement?,
    maxElements: Int,
    deadline: Date,
    now: () -> Date = Date.init
) -> (elements: [ObservedElement], truncated: Bool) {
    var collected: [ObservedElement] = []
    var queue: [Node] = [root]
    var truncated = false
    var index = 0

    while !queue.isEmpty {
        if collected.count >= maxElements || now() >= deadline {
            truncated = true
            break
        }
        let node = queue.removeFirst()
        if let observed = describe(node, index + 1) {
            collected.append(observed)
            index += 1
        }
        queue.append(contentsOf: children(node))
    }
    return (collected, truncated)
}

