// Standalone regression test for the native accessibility tree that replaced
// the Peekaboo `see` subprocess.
//
// The bug this guards: `runPeekabooJSON` waited on the helper with an unbounded
// `proc.waitUntilExit()`. Peekaboo carries its own bundle id, so it re-asks for
// TCC even when Owletto is granted — and that prompt waits for a human. On an
// unattended Mac the wait never ended, and because the operation held the
// device worker's execution slot, the worker stopped polling *permanently*
// while Owletto.app kept running and looking healthy. `executing observe` was
// the last line in owletto.log before the device went dark, twice out of twice.
//
// So the thing under test is not "does it read a tree" — it is "can any single
// unresponsive node stop us". `flatten` is generic over the node type precisely
// so both bounds can be driven here without a live AX tree: an infinite tree
// must terminate on the element cap, and a slow tree must terminate on the
// deadline.
//
// Coverage limit: the real `walk` binds `children`/`describe` to the AX API and
// sets AXUIElementSetMessagingTimeout on the root. That per-call ceiling is not
// observable from here — it is left to review. What is pinned is that whatever
// traversal is handed those bounds honours them.
//
//   swiftc apps/mac/Owletto/MacAccessibilityTree.swift \
//          apps/mac/Tests/AccessibilityTreeTests.swift -o /tmp/accessibility-tree-test \
//   && /tmp/accessibility-tree-test

import Foundation

// `MacAccessibilityTree.swift` throws ComputerUseError, which lives in the app
// target we deliberately do not compile here. Minimal stand-in with the two
// cases this file can reach.
enum ComputerUseError: LocalizedError {
    case invalidJob(String)
    case invalidInput(String)
    case platformFailed(String)

    var errorDescription: String? {
        switch self {
        case .invalidJob(let m), .invalidInput(let m), .platformFailed(let m): return m
        }
    }
}

/// A node that always reports two children — an infinite tree. Only a bound can
/// end this walk.
private struct EndlessNode {
    let depth: Int
}

@main
struct AccessibilityTreeTests {
    static var failures = 0

    static func check(_ condition: Bool, _ label: String) {
        if condition {
            print("  ok   \(label)")
        } else {
            print("  FAIL \(label)")
            failures += 1
        }
    }

    static func element(_ index: Int, title: String = "", role: String = "AXButton") -> ObservedElement {
        ObservedElement(
            id: "elem_\(index)",
            role: role,
            title: title,
            label: "",
            frame: CGRect(x: 10, y: 20, width: 100, height: 40),
            enabled: true
        )
    }

    // MARK: - The bounds (the actual fix)

    static func testElementCapTerminatesInfiniteTree() {
        let result = AccessibilityTree.flatten(
            root: EndlessNode(depth: 0),
            children: { [EndlessNode(depth: $0.depth + 1), EndlessNode(depth: $0.depth + 1)] },
            describe: { node, index in element(index, title: "d\(node.depth)") },
            maxElements: 25,
            deadline: Date().addingTimeInterval(60)
        )
        check(result.elements.count == 25, "infinite tree stops at maxElements (got \(result.elements.count))")
        check(result.truncated, "infinite tree reports truncated")
    }

    static func testDeadlineTerminatesSlowTree() {
        // Clock jumps past the deadline after a few reads: a tree that answers,
        // but too slowly to finish. Without the deadline this runs forever.
        var ticks = 0
        let start = Date(timeIntervalSince1970: 1_000_000)
        let result = AccessibilityTree.flatten(
            root: EndlessNode(depth: 0),
            children: { [EndlessNode(depth: $0.depth + 1), EndlessNode(depth: $0.depth + 1)] },
            describe: { node, index in element(index, title: "d\(node.depth)") },
            maxElements: 10_000,
            deadline: start.addingTimeInterval(3),
            now: {
                ticks += 1
                // Well under the deadline for the first few, then past it.
                return start.addingTimeInterval(ticks < 5 ? 0 : 10)
            }
        )
        check(result.elements.count == 4, "slow tree stops at the deadline (got \(result.elements.count))")
        check(result.truncated, "slow tree reports truncated")
    }

    static func testCompleteTreeIsNotMarkedTruncated() {
        var handed = 0
        let result = AccessibilityTree.flatten(
            root: EndlessNode(depth: 0),
            children: { _ in handed += 1; return handed <= 2 ? [EndlessNode(depth: 1)] : [] },
            describe: { node, index in element(index, title: "d\(node.depth)") },
            maxElements: 100,
            deadline: Date().addingTimeInterval(60)
        )
        check(result.elements.count == 3, "finite tree returns every element (got \(result.elements.count))")
        check(!result.truncated, "finite tree is not marked truncated")
    }

    static func testDescribeSkipIsNotCountedAsAnElement() {
        // Zero-frame nodes are dropped by the real `describe`. Ids must stay
        // dense, or an id in the payload would not match its own index.
        let result = AccessibilityTree.flatten(
            root: EndlessNode(depth: 0),
            children: { $0.depth < 3 ? [EndlessNode(depth: $0.depth + 1)] : [] },
            describe: { node, index in node.depth % 2 == 0 ? element(index) : nil },
            maxElements: 100,
            deadline: Date().addingTimeInterval(60)
        )
        check(result.elements.map(\.id) == ["elem_1", "elem_2"], "ids stay dense across skipped nodes (got \(result.elements.map(\.id)))")
    }

    // MARK: - Snapshot store

    static func testSnapshotStoreEvictsOldest() {
        let store = ObserveSnapshotStore(capacity: 2)
        store.put([element(1)], id: "a")
        store.put([element(2)], id: "b")
        store.put([element(3)], id: "c")
        check(store.get("a") == nil, "oldest snapshot is evicted at capacity")
        check(store.get("b") != nil, "second snapshot survives")
        check(store.get("c") != nil, "newest snapshot survives")
    }

    static func testSnapshotStoreRoundTrips() {
        let store = ObserveSnapshotStore(capacity: 4)
        let id = store.put([element(1, title: "Approve")])
        check(store.get(id)?.first?.title == "Approve", "snapshot round-trips by id")
        check(!id.isEmpty, "put returns a usable snapshot id")
    }

    // MARK: - Resolution

    static func testResolveByElementID() throws {
        let elements = [element(1, title: "Cancel"), element(2, title: "Approve")]
        let hit = try AccessibilityTree.resolve(elementID: "elem_2", query: nil, in: elements)
        check(hit.title == "Approve", "element_id resolves to the right element")
    }

    static func testExpiredElementIDThrowsRatherThanGuessing() {
        // Falling back to a fresh walk here would click a DIFFERENT element than
        // the caller saw. An error is the safe answer.
        do {
            _ = try AccessibilityTree.resolve(elementID: "elem_99", query: nil, in: [element(1)])
            check(false, "unknown element_id throws")
        } catch {
            let msg = error.localizedDescription
            check(msg.contains("elem_99") && msg.contains("observe"), "error names the id and the remedy (got: \(msg))")
        }
    }

    static func testResolveByQueryPrefersTheTightestMatch() throws {
        let elements = [
            element(1, title: "Approve this deployment request"),
            element(2, title: "Approve"),
        ]
        let hit = try AccessibilityTree.resolve(elementID: nil, query: "approve", in: elements)
        check(hit.id == "elem_2", "query prefers the shortest matching label (got \(hit.id))")
    }

    static func testQueryWithNoMatchThrows() {
        do {
            _ = try AccessibilityTree.resolve(elementID: nil, query: "nonexistent", in: [element(1, title: "Approve")])
            check(false, "unmatched query throws")
        } catch {
            check(error.localizedDescription.contains("nonexistent"), "unmatched query names the query")
        }
    }

    static func testNoTargetAtAllThrows() {
        do {
            _ = try AccessibilityTree.resolve(elementID: nil, query: nil, in: [element(1)])
            check(false, "missing target throws")
        } catch {
            check(error.localizedDescription.contains("x/y"), "error points at the coordinate fallback")
        }
    }

    // MARK: - Geometry

    static func testCentreIsTheClickPoint() {
        let el = ObservedElement(
            id: "elem_1", role: "AXButton", title: "", label: "",
            frame: CGRect(x: 100, y: 200, width: 60, height: 20), enabled: true
        )
        check(el.centre == CGPoint(x: 130, y: 210), "centre is the middle of the frame (got \(el.centre))")
    }

    static func testMatchesIgnoresCaseAndSearchesLabelAndRole() {
        let el = ObservedElement(
            id: "elem_1", role: "AXButton", title: "Send", label: "Submit the form",
            frame: CGRect(x: 0, y: 0, width: 1, height: 1), enabled: true
        )
        check(el.matches(query: "send"), "matches title case-insensitively")
        check(el.matches(query: "submit the"), "matches the label")
        check(el.matches(query: "axbutton"), "matches the role")
        check(!el.matches(query: "delete"), "does not match unrelated text")
        check(!el.matches(query: "   "), "blank query never matches")
    }

    static func main() {
        print("AccessibilityTreeTests")
        testElementCapTerminatesInfiniteTree()
        testDeadlineTerminatesSlowTree()
        testCompleteTreeIsNotMarkedTruncated()
        testDescribeSkipIsNotCountedAsAnElement()
        testSnapshotStoreEvictsOldest()
        testSnapshotStoreRoundTrips()
        try? testResolveByElementID()
        testExpiredElementIDThrowsRatherThanGuessing()
        try? testResolveByQueryPrefersTheTightestMatch()
        testQueryWithNoMatchThrows()
        testNoTargetAtAllThrows()
        testCentreIsTheClickPoint()
        testMatchesIgnoresCaseAndSearchesLabelAndRole()

        print(failures == 0 ? "\nPASS" : "\n\(failures) FAILURE(S)")
        exit(failures == 0 ? 0 : 1)
    }
}

