export default async (ctx, client) => {
  const op = (k: string, i: any = {}) =>
    client.operations.execute({ connection_id: 447, operation_key: k, input: i });

  const out: any = {};
  // 1. Did the TCC grants survive the reinstall?
  const perms: any = await op("permissions");
  out.permissions = (perms?.output?.data?.permissions ?? []).map((p: any) => `${p.name}=${p.isGranted}`);

  // 2. Does observe return a native tree?
  const t0 = Date.now?.() ?? 0;
  const obs: any = await op("observe", { target: { app: "Ghostty" }, max_elements: 40 });
  const d = obs?.output?.data ?? {};
  out.observe = {
    backend: obs?.output?.backend,
    element_count: d.element_count,
    truncated: d.truncated ?? false,
    has_snapshot: typeof d.snapshot_id === "string" && d.snapshot_id.length > 0,
    first: (d.ui_elements ?? []).slice(0, 3),
  };
  return out;
}

export default async (ctx, client) => {
  const op = (c: number, k: string, i: any = {}) =>
    client.operations.execute({ connection_id: c, operation_key: k, input: i });

  const results: any[] = [];
  const targets = [
    { app: "Ghostty" },
    { app: "Google Chrome" },
    { app: "Finder" },
    { app: "Owletto" },
    { app: "Slack" },
  ];
  for (const target of targets) {
    try {
      const r: any = await op(447, "observe", { target, max_elements: 200, include_screenshot: false });
      results.push({ target: target.app, ok: true, n: r?.output?.data?.element_count, truncated: r?.output?.data?.truncated ?? false });
    } catch (e: any) {
      results.push({ target: target.app, ok: false, err: String(e?.message ?? e).slice(0, 90) });
    }
  }
  // The proof: after five observes, is the worker still claiming runs?
  const alive: any = await op(464, "run", { command: "echo STILL_POLLING; date -u +%H:%M:%S" });
  return { results, after: alive?.output?.stdout };
}

export default async function () {
  return await client.operations.execute({ connection_id: 447, operation_key: "observe", input: { app: "Finder" } });
}

