func clickNative(_ input: [String: AnyJSONValue]) throws -> [String: Any] {
    try requireInputAccess()
    guard let x = input.double("x"), let y = input.double("y") else {
        throw ComputerUseError.invalidInput("native click requires x and y coordinates")
    }
    let point = Self.screenPoint(x: x, y: y)
    let button: CGMouseButton
    var downType: CGEventType
    var upType: CGEventType
    switch input.string("click_type") ?? "single" {
    case "right":
        button = .right
        downType = .rightMouseDown
        upType = .rightMouseUp
    default:
        button = .left
        downType = .leftMouseDown
        upType = .leftMouseUp
    }
    let src = CGEventSource(stateID: .hidSystemState)
    CGEvent(mouseEventSource: src, mouseType: .mouseMoved, mouseCursorPosition: point, mouseButton: button)?
        .post(tap: .cghidEventTap)
    CGEvent(mouseEventSource: src, mouseType: downType, mouseCursorPosition: point, mouseButton: button)?
        .post(tap: .cghidEventTap)
    CGEvent(mouseEventSource: src, mouseType: upType, mouseCursorPosition: point, mouseButton: button)?
        .post(tap: .cghidEventTap)
    if input.string("click_type") == "double" {
        CGEvent(mouseEventSource: src, mouseType: downType, mouseCursorPosition: point, mouseButton: button)?
            .post(tap: .cghidEventTap)
        CGEvent(mouseEventSource: src, mouseType: upType, mouseCursorPosition: point, mouseButton: button)?
            .post(tap: .cghidEventTap)
    }
    return ["success": true, "data": ["x": x, "y": y, "click_type": input.string("click_type") ?? "single"]]
}

func moveMouseNative(_ input: [String: AnyJSONValue]) throws -> [String: Any] {
    try requireInputAccess()
    guard let x = input.double("x"), let y = input.double("y") else {
        throw ComputerUseError.invalidInput("move_mouse requires x and y")
    }
    let point = Self.screenPoint(x: x, y: y)
    CGEvent(
        mouseEventSource: CGEventSource(stateID: .hidSystemState),
        mouseType: .mouseMoved,
        mouseCursorPosition: point,
        mouseButton: .left
    )?.post(tap: .cghidEventTap)
    return ["success": true, "data": ["x": x, "y": y]]
}

func scrollNative(_ input: [String: AnyJSONValue]) throws -> [String: Any] {
    try requireInputAccess()
    guard let direction = input.string("direction") else {
        throw ComputerUseError.invalidInput("scroll requires direction")
    }
    }
    try postHotkeyNative(keys: keys, holdMs: input.int("hold_ms") ?? 50)
    return ["success": true, "data": ["keys": keys]]
}

func focusWindowNative(_ input: [String: AnyJSONValue]) throws -> [String: Any] {
    if let windowID = input.int("window_id") {
        let pid = try pidForWindowID(windowID)
        guard let app = NSRunningApplication(processIdentifier: pid) else {
            throw ComputerUseError.platformFailed("No running app for window \(windowID)")
        }
        app.activate(options: [.activateIgnoringOtherApps])
        return ["success": true, "data": ["window_id": windowID, "pid": Int(pid)]]
    }
    if let appName = input.string("app") {
        guard let app = Self.resolveRunningApp(named: appName) else {
            throw ComputerUseError.platformFailed("App not found: \(appName)")
        }
        app.activate(options: [.activateIgnoringOtherApps])
        return ["success": true, "data": ["app": app.localizedName ?? appName]]
    }
    throw ComputerUseError.invalidInput("focus_window requires app or window_id")
}

func launchAppNative(_ input: [String: AnyJSONValue]) throws -> [String: Any] {
    let activate = input.bool("activate") != false
    let config = NSWorkspace.OpenConfiguration()
    config.activates = activate
    if let bundleID = input.string("bundle_id") {
        if let running = NSWorkspace.shared.runningApplications.first(where: { $0.bundleIdentifier == bundleID }) {
            if activate { running.activate(options: [.activateIgnoringOtherApps]) }
            return ["success": true, "data": ["bundle_id": bundleID, "already_running": true]]
        }
        guard let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            throw ComputerUseError.platformFailed("Unknown bundle id \(bundleID)")
        }
        var launched: NSRunningApplication?
        let sem = DispatchSemaphore(value: 0)
        NSWorkspace.shared.openApplication(at: url, configuration: config) { app, _ in
            launched = app
            sem.signal()
        }
        sem.wait()
        return ["success": true, "data": ["bundle_id": bundleID, "pid": launched.map { Int($0.processIdentifier) } as Any]]
    }
    guard let appName = input.string("app") else {
        throw ComputerUseError.invalidInput("launch_app requires app or bundle_id")
    }
    if let running = Self.resolveRunningApp(named: appName) {
        if activate { running.activate(options: [.activateIgnoringOtherApps]) }
        return ["success": true, "data": ["app": appName, "already_running": true]]
    }
    guard NSWorkspace.shared.launchApplication(appName),
          let launched = Self.resolveRunningApp(named: appName) else {
        throw ComputerUseError.platformFailed("Could not launch \(appName)")
    }
    if activate { launched.activate(options: [.activateIgnoringOtherApps]) }
    return ["success": true, "data": ["app": appName, "pid": Int(launched.processIdentifier)]]
}

