/// A whole text view's contents can be megabytes. Enough to identify a field
/// and read back what was typed, not enough to blow up the payload.
static let maxValueLength = 256

/// Read one element's attributes. Elements with no frame (containers,
/// offscreen items) are skipped — nothing can be clicked at no coordinates.
static func describe(_ element: AXUIElement, index: Int) -> ObservedElement? {
    guard let frame = frame(of: element) else { return nil }
    guard frame.width > 0, frame.height > 0 else { return nil }
    return ObservedElement(
        id: "elem_\(index)",
        role: string(element, kAXRoleAttribute) ?? "",
        title: string(element, kAXTitleAttribute) ?? "",
        label: string(element, kAXDescriptionAttribute) ?? "",
        value: truncate(string(element, kAXValueAttribute) ?? ""),
        frame: frame,
        enabled: bool(element, kAXEnabledAttribute) ?? true
    )
}

static func truncate(_ text: String) -> String {
    text.count <= maxValueLength ? text : String(text.prefix(maxValueLength)) + "…"
}

