func scrollTargetNative(_ input: [String: AnyJSONValue]) throws -> [String: Any] {
    try requireInputAccess()
    // `scroll` calls its element `target`, where `click` says element_id/query.
    // Without this translation the resolver saw neither key and every
    // scroll-by-element failed with a message about clicking.
    let hit = try resolveElement(Self.withElementTarget(input))

/// How a free-form `target` string should be resolved.
enum ElementTarget: Equatable {
    case elementID(String)
    case query(String)
}

/// `scroll` takes a single `target` where `click` takes element_id OR query.
/// An `elem_N` string can only have come from a snapshot, so treat it as an
/// id; anything else is text to match.
static func elementTarget(from target: String) -> ElementTarget {
    target.hasPrefix("elem_") ? .elementID(target) : .query(target)
}

/// Resolve the element a `click`/`scroll` is aimed at.

/// Rewrite `scroll`'s `target` into the element_id/query keys the resolver
/// reads. Explicit keys win, so a caller that passes both is not overridden.
static func withElementTarget(_ input: [String: AnyJSONValue]) -> [String: AnyJSONValue] {
    guard input.string("element_id") == nil,
          input.string("query") == nil,
          let target = input.string("target") else { return input }
    var out = input
    switch AccessibilityTree.elementTarget(from: target) {
    case .elementID(let id): out["element_id"] = .string(id)
    case .query(let text): out["query"] = .string(text)
    }
    return out
}

/// Elements a `click`/`scroll` resolves against: a prior snapshot when one is
/// named, otherwise a fresh walk of the target.

case "scroll":
    // `target` is what names an element. A bare `snapshot_id` does not —
    // routing on it sent pointer-relative scrolls down the element path,
    // where they failed for want of a target.
    output = input.string("target") != nil
        ? try scrollTargetNative(input)
        : try scrollNative(input)

