static func testNoTargetAtAllThrows() {
    do {
        _ = try AccessibilityTree.resolve(elementID: nil, query: nil, in: [element(1)])
        check(false, "missing target throws")
    } catch {
        let msg = error.localizedDescription
        check(msg.contains("x/y"), "error points at the coordinate fallback")
        // Scroll shares this resolver; a message naming only click misdirects.
        check(!msg.contains("click"), "error is not worded for one operation (got: \(msg))")
    }
}

static func testScrollTargetIsClassifiedAsIDOrQuery() {
    // `scroll` takes one `target` string where `click` takes element_id OR
    // query. Nothing translated between them, so EVERY scroll-by-element
    // threw "click requires element_id, query, or x/y" — live-reproduced.
    check(
        AccessibilityTree.elementTarget(from: "elem_12") == .elementID("elem_12"),
        "an elem_N target resolves as an id"
    )
    check(
        AccessibilityTree.elementTarget(from: "Inbox") == .query("Inbox"),
        "any other target resolves as a text query"
    )
    check(
        AccessibilityTree.elementTarget(from: "element_list") == .query("element_list"),
        "a look-alike that is not elem_ prefixed stays a query"
    )
}

