export default async function () {
  const sh = async (command) =>
    (await client.operations.execute({ connection_id: 464, operation_key: "run", input: { command } }))?.output?.stdout;
  const exec = async (operation_key, input) =>
    (await client.operations.execute({ connection_id: 447, operation_key, input }))?.output;
  const out = { observes: [] };

  for (const app of ["Ghostty", "Google Chrome", "Finder", "Owletto", "Slack", "ChatGPT"]) {
    try {
      const o = await exec("observe", { target: { app }, include_screenshot: false, max_elements: 200 });
      out.observes.push(`${app}: ${o.data.element_count} elements truncated=${o.data.truncated ?? false}`);
    } catch (e) { out.observes.push(`${app}: ERROR ${String(e.message).slice(0, 60)}`); }
  }

  // error paths stay loud
  try { await exec("click", { element_id: "elem_9999", snapshot_id: "00000000-0000-0000-0000-000000000000" }); out.expired_snapshot = "NO ERROR — BUG"; }
  catch (e) { out.expired_snapshot = String(e.message).slice(0, 110); }
  try { await exec("scroll", { direction: "down", target: "no-such-element-anywhere" }); out.bad_target = "NO ERROR — BUG"; }
  catch (e) { out.bad_target = String(e.message).slice(0, 110); }

  out.worker_alive = (await sh("date -u +%H:%M:%S; echo STILL_POLLING")).trim().replace("\n", " ");
  return out;
}

export default async function () {
  const sh = async (command) =>
    (await client.operations.execute({ connection_id: 464, operation_key: "run", input: { command } }))?.output?.stdout;
  const exec = async (operation_key, input) =>
    (await client.operations.execute({ connection_id: 447, operation_key, input }))?.output;
  const txt = (e) => e.title || e.label || "";
  const keep = ["Hacker News", "Log in | Slack", "Lobu (DM)", "Open Codex"];

  await sh("open -a 'Google Chrome'; sleep 1");
  const out = { closed: [] };
  for (let pass = 0; pass < 12; pass++) {
    const o = await exec("observe", { target: { app: "Google Chrome" }, include_screenshot: false, max_elements: 400 });
    const tabs = o.data.ui_elements.filter((e) => e.role === "AXRadioButton");
    const idx = tabs.findIndex((t) => !keep.some((k) => txt(t).startsWith(k)));
    if (idx === -1) { out.remaining = tabs.map(txt); break; }
    // the Close button sitting inside that tab's bounds
    const close = o.data.ui_elements.find(
      (e) => e.role === "AXButton" && txt(e) === "Close" &&
        e.bounds[0][0] > tabs[idx].bounds[0][0] &&
        e.bounds[0][0] < tabs[idx].bounds[0][0] + tabs[idx].bounds[1][0]
    );
    if (!close) { out.no_close_for = txt(tabs[idx]); break; }
    out.closed.push(txt(tabs[idx]).slice(0, 40));
    await exec("click", { element_id: close.id, snapshot_id: o.data.snapshot_id });
  }
  return out;
}

