static func testWindowTargetMatching() {
    // `window_title`/`window_index` are declared in the manifest but were
    // silently ignored: a title-only target fell through to the frontmost
    // app, so observe walked and screenshotted a window nobody asked for.
    let windows = [
        AccessibilityTree.WindowRef(index: 0, title: "Inbox — Mail", id: 11),
        AccessibilityTree.WindowRef(index: 1, title: "Drafts — Mail", id: 22),
        AccessibilityTree.WindowRef(index: 2, title: "Inbox — Archive", id: 33),
    ]
    check(
        AccessibilityTree.matchWindow(titled: "drafts", index: nil, in: windows)?.id == 22,
        "title matches case-insensitively on a substring"
    )
    check(
        AccessibilityTree.matchWindow(titled: nil, index: 2, in: windows)?.id == 33,
        "index matches exactly"
    )
    check(
        AccessibilityTree.matchWindow(titled: "Inbox", index: 2, in: windows)?.id == 33,
        "title and index must both hold"
    )
    check(
        AccessibilityTree.matchWindow(titled: "Inbox", index: 1, in: windows) == nil,
        "a title that matches the wrong index does not match"
    )
    // The whole point: no match must be reportable as nothing, never as the
    // first window — a silent fallback acts on the wrong window.
    check(
        AccessibilityTree.matchWindow(titled: "Nonexistent", index: nil, in: windows) == nil,
        "an unmatched title returns nil rather than falling back"
    )
    check(
        AccessibilityTree.matchWindow(titled: "Inbox", index: nil, in: []) == nil,
        "no windows returns nil"
    )
}

