export default async function () {
  const sh = async (command) =>
    (await client.operations.execute({ connection_id: 464, operation_key: "run", input: { command } }))?.output?.stdout;
  const exec = async (operation_key, input) =>
    (await client.operations.execute({ connection_id: 447, operation_key, input }))?.output;
  const out = {};

  const wins = (await exec("list_windows", { app: "Google Chrome" })).data.windows || [];
  out.chrome_windows = wins.map((w) => `${w.index}:"${w.title}" id=${w.windowID}`);
  const ghost = (await exec("list_windows", { app: "Ghostty" })).data.windows || [];
  out.ghostty_windows = ghost.map((w) => `${w.index}:"${w.title}" id=${w.windowID}`);

  // A: observe targeting a window by TITLE — used to silently observe frontmost
  const byTitle = await exec("observe", {
    target: { app: "Google Chrome", window_title: "Codex" }, include_screenshot: true, max_elements: 50,
  });
  out.A_by_title = { pid: byTitle.data.pid, window_id: byTitle.data.window_id, count: byTitle.data.element_count };

  // B: observe targeting by INDEX
  const byIndex = await exec("observe", {
    target: { app: "Ghostty", window_index: 1 }, include_screenshot: true, max_elements: 50,
  });
  out.B_by_index = { pid: byIndex.data.pid, window_id: byIndex.data.window_id, count: byIndex.data.element_count };

  // C: an unmatched title must throw, never silently fall back to frontmost
  try {
    await exec("observe", { target: { app: "Google Chrome", window_title: "no-such-window-anywhere" }, include_screenshot: false });
    out.C_unmatched = "NO ERROR — SILENT FALLBACK BUG";
  } catch (e) { out.C_unmatched = String(e.message).slice(0, 120); }

  // D: focus_window by index now routes to the target path
  out.D_focus_by_index = (await exec("focus_window", { app: "Ghostty", window_index: 0 })).data;
  out.D_front = (await sh("sleep 1; lsappinfo info -only name $(lsappinfo front)")).trim();
  return out;
}

